"""Layer 15 MLP down-projection, component 5761.

What it does: a "decimal point" detector. Its activation jumps up on the "." that sits
between digits of a number ("2.5", "$6.99", "PM2.5", "1.45"), and less on the ":" and ","
inside numbers ("10,000", "12:30"). Inside a number that starts a line, as in a numbered
list ("1." then newline), the dot is weak. A number after a currency or approximation sign
("$", "≈") is strong. The chat role word "assistant" is pushed negative. Everywhere else it
hovers near zero with no clear pattern, so the program predicts 0 there.

The rules read only the prefix (the program is causal):
  - "." right after a digit (same document) -> 2.2; 0.6 if the number starts a line;
    4.0 if a currency or approximation sign comes right before the number
  - "," or ":" right after a digit          -> 0.5 / 1.0
  - "assistant"                             -> -2.5
  - anything else                           -> 0.0
"""

READS = ()

DIGITS = set("0123456789")
SEPARATORS = {".": 2.2, ",": 0.5, ":": 1.0}
ROLE_WORDS = {"assistant": -2.5}
MONEY_OR_APPROX = {"$", " $", "\\$", " \\$", "≈", " ≈", "~", " ~"}


def number_start(tokens, docs, end):
    """Index of the token just before the digit run that ends at `end` (exclusive)."""
    k = end - 1
    while k >= 0 and tokens[k] in DIGITS and docs[k] == docs[end]:
        k -= 1
    return k


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    last = len(tokens) - 1
    cur = tokens[last]
    value = 0.0
    if cur in ROLE_WORDS:
        value = ROLE_WORDS[cur]
    elif cur in SEPARATORS and last > 0 and tokens[last - 1] in DIGITS and docs[last - 1] == docs[last]:
        value = SEPARATORS[cur]
        if cur == ".":
            k = number_start(tokens, docs, last)
            before = tokens[k] if k >= 0 and docs[k] == docs[last] else "\n"
            if "\n" in before:
                value = 0.6
            elif before in MONEY_OR_APPROX:
                value = 4.0
    return carry, float(value)

"""Present-perfect verb groups: 'has/have/had (been) + past participle'.

The component is a "perfect aspect" signal in the residual stream. It is not one word: it
peaks on the words of a present-perfect verb group and fades over the next few words. Its
output direction promotes words like 'recently', 'since' and 'previously' (logit lens), so it
marks a recent-past perfect context. Rules, first match wins:

- 'been' (as in 'has been', 'It's been', 'had been'): strong, about 19.
- 'have', 'has', 'had', "'ve" as auxiliaries: about 6, or about 0.5 right after a modal,
  'not', 'n't' or 'to', where they are not perfect auxiliaries.
- A past-tense or past-participle verb directly after one of those cues (or after 'been'):
  about 12.
- An adverb directly after a cue ('has already', 'have since'): about 8, and a participle
  right after such an adverb: about 3.
- Any other word within three words after a cue (not punctuation): about 3.
- 'was' and 'were': about 2.
- Past-tense verbs elsewhere: about 1.5 (about 2.5 after a pronoun subject).

Everything else is 0. Lookback stays inside the current document.
"""

READS = ()

HAVE = {"have", "has", "had", "'ve", "’ve"}
PERFECT_CUE = HAVE | {"been"}
MODAL_OR_NEG = {"not", "n't", "'t", "to", "can", "could", "will", "would", "must", "may", "might", "should", "do", "does", "did"}
ADVERBS = {"already", "recently", "also", "just", "still", "ever", "always", "never", "not", "only", "now", "really", "yet", "often", "since", "previously"}
PRONOUNS = {"i", "we", "they", "he", "she", "it", "you"}
BE = {"was", "were"}
PUNCTUATION = {".", ",", "!", "?", "\n"}
IRREGULAR_PAST = {"seen", "made", "found", "done", "taken", "given", "known", "shown", "become", "gone", "written", "got", "gotten", "built", "spent", "lost", "held", "kept", "brought", "bought", "caught", "taught", "thought", "sold", "told", "heard", "read", "left", "felt", "begun", "chosen", "driven", "eaten", "fallen", "forgotten", "grown", "led", "paid", "said", "sent", "won", "put", "set", "run", "cut", "hit", "meant", "took", "became", "came", "went", "saw", "gave", "wrote", "ran", "ate", "drew", "began", "did"}


def is_past_participle_or_past(w):
    return w in IRREGULAR_PAST or (w.endswith("ed") and len(w) > 3)


def step(carry, prefix, upstream):
    # Up to six tokens of this document, lowercased and stripped; the newest is last.
    n = 1
    while n < 6 and n < len(prefix.token_strings) and prefix.document_ids[-1 - n] == prefix.document_ids[-1]:
        n += 1
    words = [s.strip().lower() for s in prefix.token_strings[-n:]]
    w = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""

    if w == "been":
        return carry, 19.0
    if w in HAVE:
        return carry, 0.5 if prev in MODAL_OR_NEG else 6.0
    if prev in PERFECT_CUE and is_past_participle_or_past(w):
        return carry, 12.0
    if prev in PERFECT_CUE and w in ADVERBS:
        return carry, 8.0
    if prev in ADVERBS and prev2 in PERFECT_CUE and is_past_participle_or_past(w):
        return carry, 3.0
    if any(x in PERFECT_CUE for x in words[-4:-1]) and w not in PUNCTUATION:
        return carry, 3.0
    if w in BE:
        return carry, 2.0
    if is_past_participle_or_past(w):
        return carry, 2.5 if prev in PRONOUNS else 1.5
    return carry, 0.0

"""Layer 15 MLP down_proj component 5771.

Reads a character's visible reaction in narrated fiction. It fires on:
- the chat role word "assistant" that opens a model turn (after <|im_start|>), strongest;
- a character's gesture or facial-expression verb ("she sighed", "he smiled", "nodded");
- speech and reaction verbs ("replied", "asked", "looked") and the nouns "eyes", "voice", "face";
- the comma or period right after one of those verbs.
Everything else is predicted as 0.
"""

READS = ()

ROLE_VALUE = 9.0
GESTURE = {
    " smiled", " sighed", " laughed", " nodded", " grinned", " smirked", " chuckled",
    " shrugged", " leaned", " shook", " smile", " smiles", " grin", " smirk", " sigh",
    " laughs", " widened", " frowned", " gasped", " snorted", " sneered", " paused",
}
SPEECH = {
    " said", " asked", " replied", " exclaimed", " whispered", " cried",
    " looked", " turned", " continued", " added",
}
EXPRESSION = {" eyes", " voice", " face", " gaze", " cheeks"}
ZH_REACTION = {"笑", "微笑", "笑了", "笑着", "说道", "皱", "摇头", "开口", "眉头"}
PUNCT = {",", ".", "，", "。"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if tok == "assistant" and len(toks) > 1 and toks[-2] == "<|im_start|>":
        return carry, ROLE_VALUE
    if tok in GESTURE or tok in ZH_REACTION:
        return carry, 8.0
    if tok in SPEECH or tok in EXPRESSION:
        return carry, 2.0
    if tok in PUNCT and len(toks) > 1 and (toks[-2] in GESTURE or toks[-2] in SPEECH):
        return carry, 3.0
    return carry, 0.0

"""Layer 15 MLP down_proj, component 5775: a weak, mostly negative clause-boundary feature.

Its activation goes most negative where the text has just closed a quoted or introductory
unit and a new clause (often with a person as subject: he, she, they, a name) is expected:
- a closing quotation mark after a comma, ! or ? (',"', ',”', '!"', '?”'): about -3.5;
- a closing quote after a full stop ('."', '.”'): about -1;
- a comma that ends an introductory phrase opening a sentence ("In his youth,",
  "After a few commonplaces,"): about -1.2;
- other commas: about -0.2;
- 'the' right after a comma or closing quote (a new subject noun phrase): about -0.5;
- clause openers (that, which, when, where, what, if, how, why, whether, who) and 'by', 'for':
  about -0.4;
- mid-phrase 'of', 'is', 'was', '=', ':': slightly positive, +0.1;
- everything else: 0.

The values are group means fitted on training rows. The program reads only the prefix:
it tracks the current sentence (its first word and comma count) and the previous token.
It explains only about 2% of the variance: most of the component is diffuse.
"""

READS = ()

# Words that open an introductory phrase at the start of a sentence.
INTRO = set(
    "in on at after before during without with by to for from despite due given once "
    "when while if although though as since because upon under through over among "
    "between within following unlike instead today yesterday last later finally however "
    "therefore thus also still then so".split()
)
SENTENCE_END = set(".!?\n")
COMMAS = {",", "，"}
QUOTE_AFTER_PUNCT = {',"', ',”', '!"', '?"', '!”', '?”', '！”', '？”', ',’', '。”'}
QUOTE_AFTER_STOP = {'."', '.”'}
PUNCT_BEFORE = COMMAS | QUOTE_AFTER_PUNCT | QUOTE_AFTER_STOP
CLAUSE_OPENERS = {" that", " which", " when", " where", " what", " if", " how", " why",
                  " whether", " while", " because", " who", " by", " for"}
MID_PHRASE = {" of", " is", " was", " =", ":", " were", " be"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "prev": "", "start_word": "", "len": 0, "commas": 0}
    if carry["len"] == 0 and tok.strip():
        carry["start_word"] = tok.strip().lower()
    intro = carry["start_word"] in INTRO
    if tok in QUOTE_AFTER_PUNCT:
        value = -3.5
    elif tok in QUOTE_AFTER_STOP:
        value = -1.0
    elif tok in COMMAS:
        value = -1.2 if (intro and carry["commas"] == 0) else -0.2
    elif tok == " the" and carry["prev"] in PUNCT_BEFORE:
        value = -0.5
    elif tok in CLAUSE_OPENERS:
        value = -0.4
    elif tok in MID_PHRASE:
        value = 0.1
    else:
        value = 0.0
    # update the sentence state for the next position
    if any(ch in SENTENCE_END for ch in tok):
        carry["len"], carry["commas"] = 0, 0
    else:
        carry["len"] += 1
        if any(ch in COMMAS for ch in tok):
            carry["commas"] += 1
    carry["prev"] = tok
    return carry, float(value)

"""Layer 15 MLP unit 5778, read as a sparse "coordinator" detector.

What the component is: this component's input direction is almost entirely MLP hidden
unit 5778 of layer 15 (about 0.69 of its weight, the rest spread thinly), so its
activation is that unit's value, scaled. The unit is mostly quiet and goes strongly
negative on coordinating conjunctions that join symbolic items, e.g. "2 and 3",
"Parts A and B", "(41% and 22%)", "$x$ and $y$", "[23] or [24]", and "and" inside
"both ... and" / "two ... and" / "between ... and" pairs. Ordinary "and" after a word
is only slightly negative, and list commas after numbers are a little negative.

This program writes those rules down. It is a readable approximation: it explains
only a small share of the activation's variance, because most of the variance sits
in context that no token rule captures.
"""

READS = ()

BASE = -0.05  # the component's typical value

# Coordinating conjunctions, and how strongly each one goes negative after a symbol.
CONJ_AFTER_SYMBOL = {" and": -1.3, " or": -0.9, " nor": -0.9, " &": -0.9, "和": -0.9, "、": -0.9}
PAIR_WORDS = {"both", "two", "between", "either", "neither"}


def is_symbolic(token):
    """A number, a closing bracket or quote, a currency/math/code mark, a capital letter."""
    text = token.strip()
    if text == "":
        return True
    if text.isdigit() or (len(text) == 1 and text.isupper()):
        return True
    return text[-1] in ")]}$`\"%”"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    # Words from earlier in the same document (the last six tokens).
    recent = []
    for i in range(max(0, len(prefix.token_ids) - 7), len(prefix.token_ids) - 1):
        if prefix.document_ids[i] == prefix.document_ids[-1]:
            recent.append(prefix.token_strings[i].strip().lower())
    pair_cue = any(word in PAIR_WORDS for word in recent)

    if token in CONJ_AFTER_SYMBOL:
        if pair_cue:
            return carry, -1.5
        if is_symbolic(previous):
            return carry, CONJ_AFTER_SYMBOL[token]
        return carry, (-0.2 if token == " and" else 0.0)
    if token == "," and previous.strip().isdigit():
        return carry, -0.25
    return carry, BASE

"""Layer 15 MLP neuron 5797 (its single component): fires while the text is rewriting or
solving an algebraic equation, on the tokens that step the equation forward.

What it responds to:
- the arrow or implication sign that follows an equation ("⇒", "→"): the strongest;
- the token right after such an arrow, usually the first term of the rewritten equation
  (the space in "⇒ 24");
- words that announce an algebraic move ("Multiply both sides", "sides", "solve",
  "Thus", "So", "Therefore", "rearrange") and the line breaks that end a displayed
  equation (",\n\n", ":\n\n");
- all of these scaled up when the surrounding text is algebra: the density of math
  symbols (digits, single-letter variables, operators) over the previous 32 tokens, and
  how many algebra words ("equation", "solve", "sides", "terms", "sqrt", superscripts)
  appear in the previous 64 tokens, counting only the same document.

Ordinary prose, and math with no algebra around it, predicts about zero. The program is
a rule, not a table: a few token roles, two context measures, and one weight per role
and measure, fitted by least squares on about 4 million training positions.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MATH_WINDOW = 32
ALGEBRA_WINDOW = 64
ALGEBRA_SATURATION = 5  # this many algebra words in the window count as full context

MATH_SYMBOLS = set("0123456789=+-*/^()<>≤≥×÷²³")

ARROWS = {"⇒", "→", "=>", "-->"}

MOVE_WORDS = {
    "sides", "Multiply", "Thus", "So", "so", "Therefore", "then", "Then",
    "solve", "both", "From", "equation", "terms", "write", "rearrange",
}

LINE_BREAKS = {",\n\n", ":\n\n", ")\n\n"}

ALGEBRA_WORDS = {
    "equation", "solve", "sides", "terms", "Multiply", "rearrange",
    "Thus", "Therefore", "From", "sqrt", "²", "³",
}

# Weight per unit of math density (last 32 tokens), by the current token's role.
DENSITY_WEIGHT = {"arrow": 6.6, "after": 3.2, "word": 2.3, "break": 2.1, "math": 0.1, "other": 0.1}

# Weight per unit of algebra context (last 64 tokens), by the current token's role.
CONTEXT_WEIGHT = {"arrow": 15.7, "after": 10.1, "word": 2.5, "break": 3.0, "math": 0.8, "other": 0.5}

INTERCEPT = -0.05


def is_math(s: str) -> bool:
    core = s.strip()
    return core.isdigit() or (len(core) == 1 and core.isalpha()) or core in MATH_SYMBOLS


def is_arrow(s: str) -> bool:
    return s.strip() in ARROWS or "⇒" in s or "→" in s


def role(s: str, previous: str) -> str:
    """The current token's role in an equation-rewriting step."""
    core = s.strip()
    if is_arrow(s):
        return "arrow"
    if is_arrow(previous):
        return "after"
    if core in MOVE_WORDS:
        return "word"
    if s in LINE_BREAKS:
        return "break"
    if is_math(s):
        return "math"
    return "other"


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    doc = prefix.document_ids[t]
    # the previous 64 tokens of the same document, nearest last
    lo = max(0, t - ALGEBRA_WINDOW)
    earlier = [
        prefix.token_strings[i]
        for i in range(lo, t)
        if prefix.document_ids[i] == doc
    ]
    math_density = sum(is_math(s) for s in earlier[-MATH_WINDOW:]) / MATH_WINDOW
    algebra = min(sum(s.strip() in ALGEBRA_WORDS for s in earlier) / ALGEBRA_SATURATION, 1.0)
    previous = prefix.token_strings[t - 1] if t > 0 and prefix.document_ids[t - 1] == doc else ""
    current = role(prefix.token_strings[t], previous)
    value = (
        INTERCEPT
        + DENSITY_WEIGHT[current] * math_density
        + CONTEXT_WEIGHT[current] * algebra
    )
    return carry, float(value)

"""Layer 15 MLP down-projection, component 5805: a negative "tool / partitive phrase" detector.

Its activation is mostly negative on words that open a noun phrase still waiting for its
head noun, especially the phrases "X of" and "using/by/via/use Y":
- the word "of" (the speed of, number of, the tip of, a mix of): about -2.8;
- the word right after an instrument or means word: "using a", "via the", "by the",
  "use this" (after using: about -3; after via: -2.6; after use: -2; after by: -1.7;
  after through: -1.1);
- foreign words for "of" or "with" (de, di, des, del, durch, mit, par, por, von): about -1;
- determiners and modifiers that open a noun phrase (your, his, same, other, new,
  different, two, ...): about -0.5;
- the prepositions in, with, by, into, on, from, at, as: slightly positive, about +0.3.

Everything else predicts 0. The rules are an if/elif chain: the first matching rule gives
the value. Why these: where the component is strongly negative, its output direction
pushes the model toward predicting tool, technique and method nouns next (scanner,
algorithms, techniques, tools, methods, camera), so the negative words are the ones that
set up an instrument or a partitive. This captures only the word-level pattern, about 15%
of the activation's variance on held-out text; the rest is diffuse, context-dependent
variation over ordinary words.
"""

READS = ()

OF_WORDS = {" of", " Of", " OF", "of"}
FOREIGN = {" de", " di", " des", " del", " durch", " mit", " par", " por", " von"}
DETERMINERS = {
    " same", " other", " own", " your", " his", " my", " our", " their", " her",
    " new", " different", " single", " another", " next", " two", " this", " these",
    " simple", " small", " large", " few", " any", " each", " both",
}
PREPOSITIONS = {" in", " with", " by", " into", " on", " from", " at", " as"}
# value on the word right after each word that introduces a tool or means
MEANS_INTRO = {
    " using": -3.1, " Using": -3.1, " via": -2.6, " use": -2.0, " uses": -2.0,
    " Use": -2.0, " used": -2.0, " apply": -2.0, " applying": -2.0,
    " by": -1.7, " By": -1.7, " through": -1.1,
}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur in OF_WORDS:
        value = -2.8
    elif prev in MEANS_INTRO:
        value = MEANS_INTRO[prev]
    elif cur in FOREIGN:
        value = -1.1
    elif cur in DETERMINERS:
        value = -0.5
    elif cur in PREPOSITIONS:
        value = 0.3
    else:
        value = 0.0
    return carry, value

"""The far end of a span: the word that closes a range of time, place or number.

This component fires on the preposition or conjunction that introduces the end
of a span:
- "until", "till", and their counterparts in other languages ("jusqu'à",
  "hasta", "bis", "pana la"): strong, whether or not a start word came first;
- "to" closing a "from ... to" range, a numeric range ("2008 to 2018"), or a
  span after a dash ("2015–2018");
- "to" after a motion word, naming a destination ("went back to", "walked
  straight up to");
- "through", "since", "as of", "toward(s)": moderate.
The opening words "from" and "between" get a small value, since a span has
started there. Plain "to" (infinitive, "according to", "access to") stays near
zero, and most other tokens are zero.

The program reads only the last few words and uses small word lists. It
explains about 11% of the variance on eval rows (r about 0.35). It misses the
largest, most idiosyncratic values, and it does not model the negative values.
"""

READS = ()

# Words that open a span: a range end soon after one is a "from ... to" range.
START_WORDS = {"from", "between", "от", "de", "desde"}
# Words that end a span of time or place, in English and other languages.
UNTIL_WORDS = {"until", "till", "jusqu", "hasta", "até", "đến", "bis",
               "depuis", "tới", "pana", "până", "fino"}
# Motion words after which "to" names a destination ("went back to", "down to").
MOTION_WORDS = {
    "back", "up", "down", "straight", "inward", "outward", "toward", "towards",
    "return", "returned", "go", "went", "walked", "moved", "moves", "headed",
    "drove", "drive", "sent", "took", "get", "got", "move", "transferred",
    "carried", "dwindled", "fell", "fall", "rises", "rise", "jump", "swam",
    "nearly",
}
# Words after which "to" is a fixed phrase or infinitive, not an end or goal.
FIXED_WORDS = {
    "according", "related", "due", "access", "intrinsic", "relating",
    "contribute", "willing", "needed", "decided", "has", "is", "are", "not",
    "as", "like", "trying",
}
WINDOW = 6  # how many earlier words count as "nearby"


def step(carry, prefix, upstream):
    ts = [s.strip() for s in prefix.token_strings]
    t = ts[-1]
    prev = ts[-2] if len(ts) > 1 else ""
    before = ts[-(WINDOW + 1):-1]
    from_span = any(w in START_WORDS for w in before)

    if t in UNTIL_WORDS or (t in ("à", "'à") and prev == "jusqu"):
        return carry, 14.0
    if t == "since":
        return carry, 5.0
    if t == "through":
        return carry, 8.0 if from_span else 2.0
    if t in ("toward", "towards"):
        return carry, 4.0
    if t in ("до", "到"):
        return carry, 5.0
    if t == "of" and prev == "as":
        return carry, 10.0
    if t in ("from", "between"):
        return carry, 3.0
    if t in ("–", "-") and prev[-1:].isdigit():
        return carry, 8.0 if from_span else 4.0
    if t == "and" and "between" in before:
        return carry, 6.0
    if t == "à":
        return carry, 8.0 if from_span else 1.0
    if t != "to":
        return carry, 0.0

    # Plain "to": a span end, a destination, or a fixed phrase.
    if prev in FIXED_WORDS:
        return carry, 0.0
    if from_span:
        return carry, 8.0
    if prev.isdigit():
        return carry, 5.0
    if prev in MOTION_WORDS:
        return carry, 8.0
    return carry, 1.0

"""Layer 15 MLP hidden unit 5816 (component p-82af68dd@100000/layers.15.mlp.down_proj:5816).

The component reads the layer-15 MLP's hidden vector through a direction that is
mostly one hidden unit: unit 5816 carries about 0.61 of the direction's norm 0.86,
so the activation is roughly 0.57 times that unit's value plus small contributions
from many other units. The activation is mostly small and noisy (std 0.31), and
no simple word or position rule predicts it well. Its large negative values
appear in shell and tool-call text and around the verb "send". Through the
unembedding (a rough logit lens), a negative activation writes a direction that
favours next tokens like "send", "release", "notify", "trigger" and "broadcast".

The program is a short set of rules in human terms:
  - the first token of each document: about 0;
  - the verb "send" and its forms: negative;
  - shell and tool-call syntax ("command", "arguments", "echo", "EOF", "&&"): negative;
  - the next three tokens of a document: slightly positive;
  - everything else: the typical value, about +0.03.

It explains almost none of the variance: about 0.1% on the eval rows, and its
effect on the model's output is about the same as switching the component off.
A per-token table of mean values reaches about 2% on training rows, but it is a
table of arbitrary token ids, so it is not used here.
"""

READS = ()

BASE = 0.03
SEND_WORDS = {"send", "sends", "sent", "sending"}
SHELL_WORDS = {"command", "arguments", "echo", "eof", "&&", ">&", "bash", "ash"}


def step(carry, prefix, upstream):
    doc_prev, n = carry if carry is not None else (None, -1)
    doc = prefix.document_ids[-1]
    n = 0 if doc != doc_prev else n + 1
    word = prefix.token_strings[-1].strip().lower()
    if n == 0:
        value = 0.0
    elif word in SEND_WORDS:
        value = -0.3
    elif word in SHELL_WORDS:
        value = -0.2
    elif n <= 3:
        value = 0.09
    else:
        value = BASE
    return (doc, n), value
